-- Synthetic MentionPilot D1 export for transfer tests. Every value is invented.
-- The shape follows mentionpilot-db after migrations 0001-0010 (subset).
PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT, avatar_url TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE projects (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), check_schedule TEXT DEFAULT NULL, last_scheduled_check TEXT DEFAULT NULL);
CREATE TABLE brand_configs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, brand_name TEXT NOT NULL, brand_aliases TEXT NOT NULL DEFAULT '[]', brand_url TEXT, competitors TEXT NOT NULL DEFAULT '[]', platforms TEXT NOT NULL DEFAULT '[]', openai_api_key TEXT, anthropic_api_key TEXT, google_api_key TEXT, perplexity_api_key TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), badge_enabled INTEGER NOT NULL DEFAULT 0, ai_endpoint_url TEXT, ai_api_key TEXT, ai_model TEXT, keywords TEXT NOT NULL DEFAULT '[]', target_customer TEXT, monitoring_topics TEXT NOT NULL DEFAULT '[]', reddit_communities TEXT NOT NULL DEFAULT '[]');
CREATE TABLE prompts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, prompt_text TEXT NOT NULL, category TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE checks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'running', total_queries INTEGER NOT NULL DEFAULT 0, completed_queries INTEGER NOT NULL DEFAULT 0, brand_mention_rate REAL, summary TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), completed_at TEXT);
CREATE TABLE results (id TEXT PRIMARY KEY, check_id TEXT NOT NULL, project_id TEXT NOT NULL, prompt_id TEXT NOT NULL, platform TEXT NOT NULL, model TEXT NOT NULL, response_text TEXT NOT NULL, brand_mentioned INTEGER NOT NULL DEFAULT 0, brand_sentiment TEXT, brand_position INTEGER, competitors_mentioned TEXT NOT NULL DEFAULT '[]', citations TEXT NOT NULL DEFAULT '[]', brand_cited INTEGER NOT NULL DEFAULT 0, latency_ms INTEGER, created_at TEXT NOT NULL DEFAULT (datetime('now')), prompt_text TEXT, provider_status TEXT NOT NULL DEFAULT 'success', error_message TEXT);
CREATE TABLE findings (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, source TEXT NOT NULL, source_record_id TEXT NOT NULL, source_name TEXT NOT NULL, title TEXT NOT NULL, content TEXT, url TEXT NOT NULL, author TEXT, published_at TEXT, first_seen_at TEXT NOT NULL DEFAULT (datetime('now')), last_seen_at TEXT NOT NULL DEFAULT (datetime('now')), engagement_score INTEGER, comment_count INTEGER, relevance_score INTEGER NOT NULL DEFAULT 0, intent TEXT NOT NULL DEFAULT 'general', matched_keywords TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'new', UNIQUE(project_id, source, source_record_id));
CREATE TABLE finding_history (id TEXT PRIMARY KEY, finding_id TEXT NOT NULL, project_id TEXT NOT NULL, action TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE finding_tasks (id TEXT PRIMARY KEY, finding_id TEXT NOT NULL, project_id TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT (datetime('now')), completed_at TEXT);
